46: /**
47:  * Utility for performing type inference.
48:  *
49:  * <p>The following steps summarize the envisioned type inference process. Not all features are
50:  * implemented or exposed through the API yet (*).
51:  *
52:  * <ul>
53:  *   <li>1. Validate number of arguments.
54:  *   <li>2. (*) Apply assignment operators on the call by permuting operands and adding default
55:  *       values. These are preparations for {@link CallContext}.
56:  *   <li>3. For resolving unknown (NULL) operands: Access the outer wrapping call and try to get its
57:  *       operand type for the return type of the actual call. E.g. for {@code
58:  *       takes_string(this_function(NULL))} infer operands from {@code takes_string(NULL)} and use
59:  *       the inferred string type as the return type of {@code this_function(NULL)}.
60:  *   <li>4. Try infer unknown operands, fail if not possible.
61:  *   <li>5. (*) Check the usage of DEFAULT operands are correct using validator.isOptional().
62:  *   <li>6. Perform input type validation.
63:  *   <li>7. (Optional) Infer accumulator type.
64:  *   <li>8. Infer return type.
65:  *   <li>9. (*) In the planner: Call the strategies again at any point in time to enrich a DataType
66:  *       that has been created from a logical type with a conversion class.
67:  *   <li>10. (*) In the planner: Check for an implementation evaluation method matching the
68:  *       operands. The matching happens class-based. Thus, for example, eval(Object) is valid for
69:  *       (INT). Or eval(Object...) is valid for (INT, STRING). We rely on the conversion classes
70:  *       specified by DataType.
71:  * </ul>
72:  */
73: @Internal
74: public final class TypeInferenceUtil {
75: 
76:     /**
77:      * Runs the entire type inference process.
78:      *
79:      * @param typeInference type inference of the current call
80:      * @param callContext call context of the current call
81:      * @param surroundingInfo information about the outer wrapping call of a current function call
82:      *     for performing input type inference
83:      */
84:     public static Result runTypeInference(
85:             TypeInference typeInference,
86:             CallContext callContext,
87:             @Nullable SurroundingInfo surroundingInfo) {
88:         try {
89:             return runTypeInferenceInternal(typeInference, callContext, surroundingInfo);
90:         } catch (ValidationException e) {
91:             throw createInvalidCallException(callContext, e);
92:         } catch (Throwable t) {
93:             throw createUnexpectedException(callContext, t);
94:         }
95:     }
96: 
97:     /**
98:      * Adapts the call's argument if necessary.
99:      *
100:      * <p>This includes casts that need to be inserted, reordering of arguments (*), or insertion of
101:      * default values (*) where (*) is future work.
102:      */
103:     public static CallContext adaptArguments(
104:             TypeInference typeInference, CallContext callContext, @Nullable DataType outputType) {
105:         return adaptArguments(typeInference, callContext, outputType, true);
106:     }
107: 
108:     private static CallContext adaptArguments(
109:             TypeInference typeInference,
110:             CallContext callContext,
111:             @Nullable DataType outputType,
112:             boolean throwOnInferInputFailure) {
113:         final List<DataType> actualTypes = callContext.getArgumentDataTypes();
114: 
115:         typeInference
116:                 .getStaticArguments()
117:                 .ifPresent(
118:                         staticArgs -> {
119:                             if (actualTypes.size() != staticArgs.size()) {
120:                                 throw new ValidationException(
121:                                         String.format(
122:                                                 "Invalid number of arguments. %d arguments expected after argument expansion but %d passed.",
123:                                                 staticArgs.size(), actualTypes.size()));
124:                             }
125:                         });
126: 
127:         final AdaptedCallContext adaptedCallContext =
128:                 inferInputTypes(typeInference, callContext, outputType, throwOnInferInputFailure);
129: 
130:         // final check if the call is valid after casting
131:         final List<DataType> expectedTypes = adaptedCallContext.getArgumentDataTypes();
132:         for (int pos = 0; pos < actualTypes.size(); pos++) {
133:             final DataType expectedType = expectedTypes.get(pos);
134:             final DataType actualType = actualTypes.get(pos);
135:             if (!supportsImplicitCast(actualType.getLogicalType(), expectedType.getLogicalType())) {
136:                 if (!throwOnInferInputFailure) {
137:                     // abort the adaption, e.g. if a NULL is passed for a NOT NULL argument
138:                     return callContext;
139:                 }
140:                 throw new ValidationException(
141:                         String.format(
142:                                 "Invalid argument type at position %d. Data type %s expected but %s passed.",
143:                                 pos, expectedType, actualType));
144:             }
145:         }
146: 
147:         return adaptedCallContext;
148:     }
