605:     /**
606:      * Sets all relevant options contained in the {@link ReadableConfig} such as e.g. {@link
607:      * PipelineOptions#CLOSURE_CLEANER_LEVEL}.
608:      *
609:      * <p>It will change the value of a setting only if a corresponding option was set in the {@code
610:      * configuration}. If a key is not present, the current value of a field will remain untouched.
611:      *
612:      * @param configuration a configuration to read the values from
613:      * @param classLoader a class loader to use when loading classes
614:      */
615:     public void configure(ReadableConfig configuration, ClassLoader classLoader) {
616:         configuration
617:                 .getOptional(PipelineOptions.AUTO_GENERATE_UIDS)
618:                 .ifPresent(this::setAutoGeneratedUids);
619:         configuration
620:                 .getOptional(PipelineOptions.AUTO_WATERMARK_INTERVAL)
621:                 .ifPresent(this::setAutoWatermarkInterval);
622:         configuration
623:                 .getOptional(PipelineOptions.CLOSURE_CLEANER_LEVEL)
624:                 .ifPresent(this::setClosureCleanerLevel);
625:         configuration
626:                 .getOptional(PipelineOptions.GLOBAL_JOB_PARAMETERS)
627:                 .ifPresent(this::setGlobalJobParameters);
628: 
629:         configuration
630:                 .getOptional(MetricOptions.LATENCY_INTERVAL)
631:                 .ifPresent(interval -> setLatencyTrackingInterval(interval.toMillis()));
632: 
633:         configuration
634:                 .getOptional(StateChangelogOptions.PERIODIC_MATERIALIZATION_ENABLED)
635:                 .ifPresent(this::enablePeriodicMaterialize);
636:         configuration
637:                 .getOptional(StateChangelogOptions.PERIODIC_MATERIALIZATION_INTERVAL)
638:                 .ifPresent(this::setPeriodicMaterializeIntervalMillis);
639:         configuration
640:                 .getOptional(StateChangelogOptions.MATERIALIZATION_MAX_FAILURES_ALLOWED)
641:                 .ifPresent(this::setMaterializationMaxAllowedFailures);
642: 
643:         configuration
644:                 .getOptional(PipelineOptions.MAX_PARALLELISM)
645:                 .ifPresent(this::setMaxParallelism);
646:         configuration.getOptional(CoreOptions.DEFAULT_PARALLELISM).ifPresent(this::setParallelism);
647:         configuration.getOptional(PipelineOptions.OBJECT_REUSE).ifPresent(this::setObjectReuse);
648:         configuration
649:                 .getOptional(TaskManagerOptions.TASK_CANCELLATION_INTERVAL)
650:                 .ifPresent(interval -> setTaskCancellationInterval(interval.toMillis()));
651:         configuration
652:                 .getOptional(TaskManagerOptions.TASK_CANCELLATION_TIMEOUT)
653:                 .ifPresent(timeout -> setTaskCancellationTimeout(timeout.toMillis()));
654:         configuration
655:                 .getOptional(ExecutionOptions.SNAPSHOT_COMPRESSION)
656:                 .ifPresent(this::setUseSnapshotCompression);
657:         configuration
658:                 .getOptional(RestartStrategyOptions.RESTART_STRATEGY)
659:                 .ifPresent(s -> this.setRestartStrategy(configuration));
660: 
661:         configuration
662:                 .getOptional(JobManagerOptions.SCHEDULER)
663:                 .ifPresent(t -> this.configuration.set(JobManagerOptions.SCHEDULER, t));
664: 
665:         serializerConfig.configure(configuration, classLoader);
666:     }
