668:     private void setRestartStrategy(ReadableConfig configuration) {
669:         Map<String, String> map = configuration.toMap();
670:         Map<String, String> restartStrategyEntries = new HashMap<>();
671:         for (Map.Entry<String, String> entry : map.entrySet()) {
672:             if (entry.getKey().startsWith(RestartStrategyOptions.RESTART_STRATEGY_CONFIG_PREFIX)) {
673:                 restartStrategyEntries.put(entry.getKey(), entry.getValue());
674:             }
675:         }
676:         this.configuration.addAll(Configuration.fromMap(restartStrategyEntries));
677:     }
