769:     private ReadableConfig mergeConfigurableOptions(ReadableConfig base, ReadableConfig onTop) {
770:         if (base == null) {
771:             base = new Configuration();
772:         }
773:         Configuration configuration = new Configuration();
774:         Map<String, String> baseMap = base.toMap();
775:         Map<String, String> onTopMap = onTop.toMap();
776:         for (ConfigOption<?> option : ForStConfigurableOptions.CANDIDATE_CONFIGS) {
777:             Optional<?> baseValue = base.getOptional(option);
778:             Optional<?> topValue = onTop.getOptional(option);
779: 
780:             if (topValue.isPresent() || baseValue.isPresent()) {
781:                 Object validValue = topValue.isPresent() ? topValue.get() : baseValue.get();
782:                 ForStConfigurableOptions.checkArgumentValid(option, validValue);
783:                 configuration.setString(option.key(), validValue.toString());
784:                 String valueString =
785:                         topValue.isPresent()
786:                                 ? onTopMap.get(option.key())
787:                                 : baseMap.get(option.key());
788:                 configuration.setString(option.key(), valueString);
789:             }
790:         }
791:         return configuration;
792:     }
