1458:     @Override
1459:     public FailureResult howToHandleFailure(
1460:             Throwable failure, CompletableFuture<Map<String, String>> failureLabels) {
1461:         FailureResult failureResult = howToHandleFailure(failure);
1462:         if (reportEventsAsSpans) {
1463:             // TODO: replace with reporting as event once events are supported.
1464:             // Add reporting as callback for when the failure labeling is completed.
1465:             failureLabels.thenAcceptAsync(
