1061:     public void updateJobResourceRequirements(JobResourceRequirements jobResourceRequirements) {
1062:         if (settings.getExecutionMode() == SchedulerExecutionMode.REACTIVE) {
1063:             throw new UnsupportedOperationException(
1064:                     "Cannot change the parallelism of a job running in reactive mode.");
1065:         }
1066:         final Optional<VertexParallelismStore> maybeUpdateVertexParallelismStore =
1067:                 DefaultVertexParallelismStore.applyJobResourceRequirements(
1068:                         jobInformation.getVertexParallelismStore(), jobResourceRequirements);
1069:         if (maybeUpdateVertexParallelismStore.isPresent()) {
1070:             this.jobInformation =
1071:                     new JobGraphJobInformation(jobGraph, maybeUpdateVertexParallelismStore.get());
1072:             declareDesiredResources();
1073:             state.tryRun(
1074:                     ResourceListener.class,
1075:                     ResourceListener::onNewResourceRequirements,
1076:                     "Current state does not react to desired parallelism changes.");
1077:         }
1078:     }
