82: 
83:     // ---- Managed buffer pools ----------------------------------------------
84: 
85:     private final Object factoryLock = new Object();
86: 
87:     private final Set<LocalBufferPool> allBufferPools = new HashSet<>();
88: 
89:     private final Set<LocalBufferPool> resizableBufferPools = new HashSet<>();
90: 
91:     private int numTotalRequiredBuffers;
92: 
93:     private final Duration requestSegmentsTimeout;
94: 
95:     private final AvailabilityHelper availabilityHelper = new AvailabilityHelper();
96: 
97:     private int lastCheckedUsage = -1;
98: 
99:     @VisibleForTesting
100:     public NetworkBufferPool(int numberOfSegmentsToAllocate, int segmentSize) {
101:         this(numberOfSegmentsToAllocate, segmentSize, Duration.ofMillis(Integer.MAX_VALUE));
102:     }
