395:     @VisibleForTesting
396:     Optional<String> getUsageWarning() {
397:         int currentUsage = getEstimatedRequestedSegmentsUsage();
398:         Optional<String> message = Optional.empty();
399:         // do not log warning if the value hasn't changed to avoid spamming warnings.
400:         if (currentUsage >= USAGE_WARNING_THRESHOLD && lastCheckedUsage != currentUsage) {
401:             long totalMemory = getTotalMemory();
402:             long requestedMemory = getEstimatedRequestedMemory();
403:             long missingMemory = requestedMemory - totalMemory;
404:             message =
405:                     Optional.of(
406:                             String.format(
407:                                     "Memory usage [%d%%] is too high to satisfy all of the requests. "
408:                                             + "This can severely impact network throughput. "
409:                                             + "Please consider increasing available network memory, "
410:                                             + "or decreasing configured size of network buffer pools. "
411:                                             + "(totalMemory=%s, requestedMemory=%s, missingMemory=%s)",
412:                                     currentUsage,
413:                                     new MemorySize(totalMemory).toHumanReadableString(),
414:                                     new MemorySize(requestedMemory).toHumanReadableString(),
415:                                     new MemorySize(missingMemory).toHumanReadableString()));
416:         } else if (currentUsage < USAGE_WARNING_THRESHOLD
417:                 && lastCheckedUsage >= USAGE_WARNING_THRESHOLD) {
418:             message =
419:                     Optional.of(
420:                             String.format("Memory usage [%s%%] went back to normal", currentUsage));
421:         }
422:         lastCheckedUsage = currentUsage;
423:         return message;
424:     }
