310:     private Map<String, REPORTER_FACTORY> loadAvailableReporterFactories(
311:             @Nullable PluginManager pluginManager) {
312:         final Map<String, REPORTER_FACTORY> reporterFactories =
313:                 CollectionUtil.newHashMapWithExpectedSize(2);
314:         final Iterator<REPORTER_FACTORY> factoryIterator = getAllReporterFactories(pluginManager);
315:         // do not use streams or for-each loops here because they do not allow catching
316:         // individual
