78:     private static final Pattern LIST_PATTERN = Pattern.compile("\\s*,\\s*");
79: 
80:     private static Pattern createReporterClassPattern(String prefix, String suffix) {
81:         // [\S&&[^.]] = intersection of non-whitespace and non-period character classes
82:         return Pattern.compile(prefix + "([\\S&&[^.]]*)\\." + suffix);
83:     }
