281:     private SETUP createReporterSetup(
282:             String reporterName,
283:             MetricConfig metricConfig,
284:             REPORTER reporter,
285:             MetricFilter metricFilter,
286:             Map<String, String> additionalVariables) {
287:         reporter.open(metricConfig);
288:         return reporterSetupInfo.reporterSetupFactory.createReporterSetup(
289:                 reporterName, metricConfig, reporter, metricFilter, additionalVariables);
