292:     public List<SETUP> fromConfiguration(
293:             final Configuration configuration, @Nullable final PluginManager pluginManager) {
294: 
295:         Set<String> namedReporters = findEnabledReportersInConfiguration(configuration);
296: 
297:         if (namedReporters.isEmpty()) {
298:             return Collections.emptyList();
299:         }
300: 
301:         final List<Tuple2<String, Configuration>> reporterConfigurations =
302:                 loadReporterConfigurations(configuration, namedReporters);
303: 
304:         final Map<String, REPORTER_FACTORY> reporterFactories =
305:                 loadAvailableReporterFactories(pluginManager);
306: 
307:         return setupReporters(reporterFactories, reporterConfigurations);
308:     }
