481:     private Set<String> findEnabledReportersInConfiguration(Configuration configuration) {
482:         String includedReportersString =
483:                 configuration.get(reporterSetupInfo.reportersList, "");
484:         Set<String> includedReporters =
485:                 reporterSetupInfo
486:                         .reporterListPattern
487:                         .splitAsStream(includedReportersString)
488:                         .filter(r -> !r.isEmpty()) // splitting an empty string results in
489:                         // an empty string on jdk9+
490:                         .collect(Collectors.toSet());
491: 
492:         // use a TreeSet to make the reporter order deterministic, which is useful for testing
493:         Set<String> namedOrderedReporters = new TreeSet<>(String::compareTo);
494: 
495:         // scan entire configuration for keys starting with reporterPrefix and determine
496:         // the set of enabled reporters
497:         for (String key : configuration.keySet()) {
498:             if (key.startsWith(reporterSetupInfo.reporterPrefix)) {
499:                 Matcher matcher = reporterSetupInfo.reporterClassPattern.matcher(key);
500:                 if (matcher.matches()) {
501:                     String reporterName = matcher.group(1);
502:                     if (includedReporters.isEmpty() || includedReporters.contains(reporterName)) {
503:                         if (namedOrderedReporters.contains(reporterName)) {
504:                             LOG.warn(
505:                                     "Duplicate class configuration detected for {}{}.",
506:                                     reporterSetupInfo.reporterPrefix.replace('.', ' '),
507:                                     reporterName);
508:                         } else {
509:                             namedOrderedReporters.add(reporterName);
510:                         }
511:                     } else {
512:                         LOG.info(
513:                                 "Excluding {}{}, not configured in reporter list ({}).",
514:                                 reporterSetupInfo.reporterPrefix.replace('.', ' '),
515:                                 reporterName,
516:                                 includedReportersString);
517:                     }
518:                 }
519:             }
520:         }
521:         return namedOrderedReporters;
522:     }
523: }
