355:     private Iterator<REPORTER_FACTORY> getAllReporterFactories(
356:             @Nullable PluginManager pluginManager) {
357:         final Spliterator<REPORTER_FACTORY> factoryIteratorSPI =
358:                 ServiceLoader.load(reporterSetupInfo.factoryTypeClass).spliterator();
359:         final Spliterator<REPORTER_FACTORY> factoryIteratorPlugins =
360:                 pluginManager != null
361:                         ? Spliterators.spliteratorUnknownSize(
362:                                 pluginManager.load(reporterSetupInfo.factoryTypeClass), 0)
363:                         : Spliterators.emptySpliterator();
364: 
365:         return Stream.concat(
366:                         StreamSupport.stream(factoryIteratorPlugins, false),
367:                         StreamSupport.stream(factoryIteratorSPI, false))
368:                 .iterator();
369:     }
