128:     private void serializeSubtaskIndexAndFinishedState(
129:             int subtaskIndex, boolean isFinished, DataOutputStream dos) throws IOException {
130:         if (isFinished) {
131:             // We store a negative index for the finished subtask. In consideration
132:             // of the index 0, the negative index would start from -1.
133:             dos.writeInt(-(subtaskIndex + 1));
134:         } else {
135:             dos.writeInt(subtaskIndex);
136:         }
137:     }
