151:     @Override
152:     protected OperatorState deserializeOperatorState(
153:             DataInputStream dis, @Nullable DeserializationContext context) throws IOException {
154:         final OperatorID jobVertexId = new OperatorID(dis.readLong(), dis.readLong());
155:         final int parallelism = dis.readInt();
156:         final int maxParallelism = dis.readInt();
157: 
158:         ByteStreamStateHandle coordinateState =
159:                 deserializeAndCheckByteStreamStateHandle(dis, context);
160: 
161:         final int numSubTaskStates = dis.readInt();
162:         if (numSubTaskStates < 0) {
163:             checkState(
164:                     coordinateState == null,
165:                     "Coordinator State should be null for fully finished operator state");
166:             return new FullyFinishedOperatorState(
167:                     null, null, jobVertexId, parallelism, maxParallelism);
168:         }
169: 
170:         final OperatorState operatorState =
171:                 new OperatorState(null, null, jobVertexId, parallelism, maxParallelism);
172: 
173:         // Coordinator state
174:         operatorState.setCoordinatorState(coordinateState);
175: 
176:         // Sub task states
177:         for (int j = 0; j < numSubTaskStates; j++) {
178:             SubtaskAndFinishedState subtaskAndFinishedState =
179:                     deserializeSubtaskIndexAndFinishedState(dis);
180:             if (subtaskAndFinishedState.isFinished) {
181:                 operatorState.putState(
182:                         subtaskAndFinishedState.subtaskIndex,
183:                         FinishedOperatorSubtaskState.INSTANCE);
184:             } else {
185:                 final OperatorSubtaskState subtaskState = deserializeSubtaskState(dis, context);
186:                 operatorState.putState(subtaskAndFinishedState.subtaskIndex, subtaskState);
187:             }
188:         }
189: 
190:         return operatorState;
191:     }
