233:     private <T extends StateObject> void serializeCollection(
234:             StateObjectCollection<T> stateObjectCollection,
235:             DataOutputStream dos,
236:             BiConsumerWithException<T, DataOutputStream, IOException> cons)
237:             throws IOException {
238:         if (stateObjectCollection == null) {
239:             dos.writeInt(0);
240:         } else {
241:             dos.writeInt(stateObjectCollection.size());
242:             for (T stateObject : stateObjectCollection) {
243:                 cons.accept(stateObject, dos);
244:             }
245:         }
246:     }
