778:     private CompletableFuture<Map<String, String>> labelFailure(
779:             final TaskExecutionStateTransition taskExecutionStateTransition) {
780:         if (taskExecutionStateTransition.getExecutionState() == ExecutionState.FAILED
781:                 && !failureEnrichers.isEmpty()) {
782:             final Throwable cause = taskExecutionStateTransition.getError(userCodeClassLoader);
783:             final Context ctx =
784:                     DefaultFailureEnricherContext.forTaskFailure(
785:                             jobInfo, jobManagerJobMetricGroup, ioExecutor, userCodeClassLoader);
786:             return FailureEnricherUtils.labelFailure(
787:                     cause, ctx, getMainThreadExecutor(), failureEnrichers);
788:         }
789:         return FailureEnricherUtils.EMPTY_FAILURE_LABELS;
790:     }
