43: /**
44:  * Implements a word count which takes the input file and counts the number of occurrences of each
45:  * word in the file and writes the result back to disk.
46:  *
47:  * <p>This example shows how to use Hadoop Input Formats, how to convert Hadoop Writables to common
48:  * Java types for better usage in a Flink job and how to use Hadoop Output Formats.
49:  */
50: public class HadoopMapredCompatWordCount {
51: 
52:     public static void main(String[] args) throws Exception {
53:         if (args.length < 2) {
54:             System.err.println("Usage: WordCount <input path> <result path>");
55:             return;
56:         }
57: 
58:         final String inputPath = args[0];
59:         final String outputPath = args[1];
60: 
61:         final ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();
62: 
63:         // Set up the Hadoop Input Format
64:         HadoopInputFormat<LongWritable, Text> hadoopInputFormat =
65:                 new HadoopInputFormat<LongWritable, Text>(
66:                         new TextInputFormat(), LongWritable.class, Text.class, new JobConf());
67:         TextInputFormat.addInputPath(hadoopInputFormat.getJobConf(), new Path(inputPath));
68: 
69:         // Create a Flink job with it
70:         DataSet<Tuple2<LongWritable, Text>> text = env.createInput(hadoopInputFormat);
71: 
72:         DataSet<Tuple2<Text, LongWritable>> words =
73:                 text.flatMap(
74:                                 new HadoopMapFunction<LongWritable, Text, Text, LongWritable>(
75:                                         new Tokenizer()))
76:                         .groupBy(0)
77:                         .reduceGroup(
78:                                 new HadoopReduceCombineFunction<
79:                                         Text, LongWritable, Text, LongWritable>(
80:                                         new Counter(), new Counter()));
81: 
82:         // Set up Hadoop Output Format
83:         HadoopOutputFormat<Text, LongWritable> hadoopOutputFormat =
84:                 new HadoopOutputFormat<Text, LongWritable>(
85:                         new TextOutputFormat<Text, LongWritable>(), new JobConf());
86:         hadoopOutputFormat.getJobConf().set("mapred.textoutputformat.separator", " ");
87:         TextOutputFormat.setOutputPath(hadoopOutputFormat.getJobConf(), new Path(outputPath));
88: 
89:         // Output & Execute
90:         words.output(hadoopOutputFormat).setParallelism(1);
91:         env.execute("Hadoop Compat WordCount");
92:     }
