440:     private static class Scrambler implements Serializable {
441:         private Tuple2<IntValue, IntValue> d = new Tuple2<>(new IntValue(), new IntValue());
442: 
443:         private final boolean keyed;
444: 
445:         public Scrambler(boolean keyed) {
446:             this.keyed = keyed;
447:         }
448: 
449:         public Tuple2<IntValue, IntValue> scramble(
450:                 Tuple2<IntValue, IntValue> a, Tuple2<IntValue, IntValue> b) {
451:             /*
452:              * Scramble all fields except returned object's key
453:              *
454:              * Randomly select among four return values:
455:              *
456:              *   0) return first object (a)
457:              *   1) return second object (b)
458:              *   2) return new object
459:              *   3) return reused local object (d)
460:              */
461: 
462:             Random random = new Random(RANDOM_SEED);
463: 
464:             if (a != null && b != null) {
465:                 random.setSeed((((long) a.f0.getValue()) << 32) + b.f0.getValue());
466:             } else if (a != null) {
467:                 random.setSeed(a.f0.getValue());
468:             } else if (b != null) {
469:                 random.setSeed(b.f0.getValue());
470:             } else {
471:                 throw new RuntimeException("One of a or b should be not null");
472:             }
473: 
474:             Tuple2<IntValue, IntValue> result;
475: 
476:             switch (random.nextInt(4)) {
477:                 case 0:
478:                     result = a;
479:                     break;
480:                 case 1:
481:                     result = b;
482:                     break;
483:                 case 2:
484:                     result = d;
485:                     break;
486:                 case 3:
487:                     result = new Tuple2<>(new IntValue(), new IntValue());
488:                     break;
489:                 default:
490:                     throw new RuntimeException("Unexpected value in switch statement");
491:             }
492: 
493:             if (a == null || b == null) {
494:                 // null values are seen when processing outer joins
495:                 if (result == null) {
496:                     result = d;
497:                 }
498: 
499:                 if (a == null) {
500:                     b.f0.copyTo(result.f0);
501:                     b.f1.copyTo(result.f1);
502:                 } else {
503:                     a.f0.copyTo(result.f0);
504:                     a.f1.copyTo(result.f1);
505:                 }
506:             } else {
507:                 if (keyed) {
508:                     result.f0.setValue(a.f0.getValue());
509:                 } else {
510:                     result.f0.setValue(a.f0.getValue() + b.f0.getValue());
511:                 }
512: 
513:                 result.f1.setValue(a.f1.getValue() + b.f1.getValue());
514:             }
515: 
516:             scrambleIfNot(a, result);
517:             scrambleIfNot(b, result);
518:             scrambleIfNot(d, result);
519: 
520:             return result;
521:         }
522: 
523:         private Random random = new Random(~RANDOM_SEED);
524: 
525:         private void scrambleIfNot(Tuple2<IntValue, IntValue> t, Object o) {
526:             // verify that the tuple is not null and the same as the
527:             // comparison object, then scramble the fields
528:             if (t != null && t != o) {
529:                 t.f0.setValue(random.nextInt());
530:                 t.f1.setValue(random.nextInt());
531:             }
532:         }
533:     }
534: }
