64: /** IT test for writing savepoints. */
65: public class SavepointWriterITCase extends AbstractTestBaseJUnit4 {
66: 
67:     private static final String ACCOUNT_UID = "accounts";
68: 
69:     private static final String CURRENCY_UID = "currency";
70: 
71:     private static final String MODIFY_UID = "numbers";
72: 
73:     private static final MapStateDescriptor<String, Double> descriptor =
74:             new MapStateDescriptor<>("currency-rate", Types.STRING, Types.DOUBLE);
75: 
76:     private static final Collection<Account> accounts =
77:             Arrays.asList(new Account(1, 100.0), new Account(2, 100.0), new Account(3, 100.0));
78: 
79:     private static final Collection<CurrencyRate> currencyRates =
80:             Arrays.asList(new CurrencyRate("USD", 1.0), new CurrencyRate("EUR", 1.3));
81: 
82:     @Test
83:     public void testDefaultStateBackend() throws Exception {
84:         testStateBootstrapAndModification(null);
85:     }
86: 
87:     @Test
88:     public void testHashMapStateBackend() throws Exception {
89:         testStateBootstrapAndModification(new HashMapStateBackend());
90:     }
91: 
92:     @Test
93:     public void testEmbeddedRocksDBStateBackend() throws Exception {
94:         testStateBootstrapAndModification(new EmbeddedRocksDBStateBackend());
95:     }
96: 
97:     public void testStateBootstrapAndModification(StateBackend configuration) throws Exception {
98:         final String savepointPath = getTempDirPath(new AbstractID().toHexString());
99: 
100:         bootstrapState(configuration, savepointPath);
101: 
102:         validateBootstrap(configuration, savepointPath);
103: 
104:         final String modifyPath = getTempDirPath(new AbstractID().toHexString());
105: 
106:         modifySavepoint(configuration, savepointPath, modifyPath);
107: 
108:         validateModification(configuration, modifyPath);
109:     }
110: 
111:     private void bootstrapState(StateBackend configuration, String savepointPath) throws Exception {
112:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
113:         env.setRuntimeMode(RuntimeExecutionMode.AUTOMATIC);
114: 
115:         StateBootstrapTransformation<Account> transformation =
116:                 OperatorTransformation.bootstrapWith(env.fromData(accounts))
117:                         .keyBy(acc -> acc.id)
118:                         .transform(new AccountBootstrapper());
119: 
120:         StateBootstrapTransformation<CurrencyRate> broadcastTransformation =
121:                 OperatorTransformation.bootstrapWith(env.fromData(currencyRates))
122:                         .transform(new CurrencyBootstrapFunction());
123: 
124:         SavepointWriter writer =
125:                 configuration == null
126:                         ? SavepointWriter.newSavepoint(env, 128)
127:                         : SavepointWriter.newSavepoint(env, configuration, 128);
128: 
129:         writer.withOperator(OperatorIdentifier.forUid(ACCOUNT_UID), transformation)
130:                 .withOperator(getUidHashFromUid(CURRENCY_UID), broadcastTransformation)
131:                 .write(savepointPath);
132: 
133:         env.execute("Bootstrap");
134:     }
135: 
136:     private void validateBootstrap(StateBackend configuration, String savepointPath) throws Exception {
137:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
138: 
139:         if (configuration != null) {
140:             env.setStateBackend(configuration);
141:         }
142: 
143:         DataStream<Account> stream =
144:                 env.fromData(accounts)
145:                         .keyBy(acc -> acc.id)
146:                         .flatMap(new UpdateAndGetAccount())
147:                         .uid(ACCOUNT_UID);
148: 
149:         final CloseableIterator<Account> results = stream.collectAsync();
150: 
151:         env.fromData(currencyRates)
152:                 .connect(env.fromData(currencyRates).broadcast(descriptor))
153:                 .process(new CurrencyValidationFunction())
154:                 .uid(CURRENCY_UID)
155:                 .sinkTo(new DiscardingSink<>());
156: 
157:         final StreamGraph streamGraph = env.getStreamGraph();
158:         streamGraph.setSavepointRestoreSettings(
159:                 SavepointRestoreSettings.forPath(savepointPath, false));
160: 
161:         env.execute(streamGraph);
162: 
163:         assertThat(results).toIterable().hasSize(3);
164:         results.close();
165:     }
166: 
167:     private void modifySavepoint(StateBackend configuration, String savepointPath, String modifyPath)
168:             throws Exception {
169:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
170:         env.setRuntimeMode(RuntimeExecutionMode.AUTOMATIC);
171: 
172:         StateBootstrapTransformation<Integer> transformation =
173:                 OperatorTransformation.bootstrapWith(env.fromData(1, 2, 3))
174:                         .transform(new ModifyProcessFunction());
175: 
176:         SavepointWriter writer =
177:                 configuration == null
178:                         ? SavepointWriter.fromExistingSavepoint(env, savepointPath)
179:                         : SavepointWriter.fromExistingSavepoint(env, savepointPath, configuration);
180: 
181:         writer.removeOperator(OperatorIdentifier.forUid(CURRENCY_UID))
182:                 .withOperator(getUidHashFromUid(MODIFY_UID), transformation)
183:                 .write(modifyPath);
184: 
185:         env.execute("Modifying");
186:     }
187: 
188:     private void validateModification(StateBackend configuration, String savepointPath) throws Exception {
189:         StreamExecutionEnvironment sEnv = StreamExecutionEnvironment.getExecutionEnvironment();
190:         if (configuration != null) {
191:             sEnv.setStateBackend(configuration);
192:         }
193: 
194:         DataStream<Account> stream =
195:                 sEnv.fromData(accounts)
196:                         .keyBy(acc -> acc.id)
197:                         .flatMap(new UpdateAndGetAccount())
198:                         .uid(ACCOUNT_UID);
199: 
200:         final CloseableIterator<Account> results = stream.collectAsync();
201: 
202:         stream.map(acc -> acc.id)
203:                 .map(new StatefulOperator())
204:                 .uid(MODIFY_UID)
205:                 .sinkTo(new DiscardingSink<>());
206: 
207:         final StreamGraph streamGraph = sEnv.getStreamGraph();
208:         streamGraph.setSavepointRestoreSettings(
209:                 SavepointRestoreSettings.forPath(savepointPath, false));
210: 
211:         sEnv.execute(streamGraph);
212: 
213:         assertThat(results).toIterable().hasSize(3);
214:         results.close();
215:     }
216: 
217:     private static OperatorIdentifier getUidHashFromUid(String uid) {
218:         return OperatorIdentifier.forUidHash(
219:                 OperatorIdentifier.forUid(uid).getOperatorId().toHexString());
220:     }
