222:     /** A simple pojo. */
223:     @SuppressWarnings("WeakerAccess")
224:     public static class Account {
225:         Account(int id, double amount) {
226:             this.id = id;
227:             this.amount = amount;
228:             this.timestamp = 1000L;
229:         }
230: 
231:         public int id;
232: 
233:         public double amount;
234: 
235:         public long timestamp;
236: 
237:         @Override
238:         public boolean equals(Object obj) {
239:             return obj instanceof Account
240:                     && ((Account) obj).id == id
241:                     && ((Account) obj).amount == amount;
242:         }
243: 
244:         @Override
245:         public int hashCode() {
246:             return Objects.hash(id, amount);
247:         }
248:     }
