251:     @SuppressWarnings("WeakerAccess")
252:     public static class CurrencyRate {
253:         public String currency;
254: 
255:         public Double rate;
256: 
257:         CurrencyRate(String currency, double rate) {
258:             this.currency = currency;
259:             this.rate = rate;
260:         }
261: 
262:         @Override
263:         public boolean equals(Object obj) {
264:             return obj instanceof CurrencyRate
265:                     && ((CurrencyRate) obj).currency.equals(currency)
266:                     && ((CurrencyRate) obj).rate.equals(rate);
267:         }
268: 
269:         @Override
270:         public int hashCode() {
271:             return Objects.hash(currency, rate);
272:         }
273:     }
