275:     /** A savepoint writer function. */
276:     public static class AccountBootstrapper extends KeyedStateBootstrapFunction<Integer, Account> {
277:         ValueState<Double> state;
278: 
279:         @Override
280:         public void open(OpenContext openContext) {
281:             ValueStateDescriptor<Double> descriptor =
282:                     new ValueStateDescriptor<>("total", Types.DOUBLE);
283:             state = getRuntimeContext().getState(descriptor);
284:         }
285: 
286:         @Override
287:         public void processElement(Account value, Context ctx) throws Exception {
288:             state.update(value.amount);
289:         }
290:     }
291: 
292:     /** A streaming function bootstrapped off the state. */
293:     public static class UpdateAndGetAccount extends RichFlatMapFunction<Account, Account> {
294:         ValueState<Double> state;
295: 
296:         @Override
297:         public void open(OpenContext openContext) throws Exception {
298:             super.open(openContext);
299: 
300:             ValueStateDescriptor<Double> descriptor =
301:                     new ValueStateDescriptor<>("total", Types.DOUBLE);
302:             state = getRuntimeContext().getState(descriptor);
303:         }
304: 
305:         @Override
306:         public void flatMap(Account value, Collector<Account> out) throws Exception {
307:             Double current = state.value();
308:             if (current != null) {
309:                 value.amount += current;
310:             }
311: 
312:             state.update(value.amount);
313:             out.collect(value);
314:         }
315:     }
316: 
317:     /** A bootstrap function. */
318:     public static class ModifyProcessFunction extends StateBootstrapFunction<Integer> {
319:         List<Integer> numbers;
320: 
321:         ListState<Integer> state;
322: 
323:         @Override
324:         public void open(OpenContext openContext) {
325:             numbers = new ArrayList<>();
326:         }
327: 
328:         @Override
329:         public void processElement(Integer value, Context ctx) {
330:             numbers.add(value);
331:         }
332: 
333:         @Override
334:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
335:             state.update(numbers);
336:         }
337: 
338:         @Override
339:         public void initializeState(FunctionInitializationContext context) throws Exception {
340:             state =
341:                     context.getOperatorStateStore()
342:                             .getUnionListState(new ListStateDescriptor<>("numbers", Types.INT));
343:         }
344:     }
345: 
346:     /** A streaming function bootstrapped off the state. */
347:     public static class StatefulOperator extends RichMapFunction<Integer, Integer>
348:             implements CheckpointedFunction {
349:         List<Integer> numbers;
350: 
351:         ListState<Integer> state;
352: 
353:         @Override
354:         public void open(OpenContext openContext) {
355:             numbers = new ArrayList<>();
356:         }
357: 
358:         @Override
359:         public void snapshotState(FunctionSnapshotContext context) throws Exception {
360:             state.update(numbers);
361:         }
362: 
363:         @Override
364:         public void initializeState(FunctionInitializationContext context) throws Exception {
365:             state =
366:                     context.getOperatorStateStore()
367:                             .getUnionListState(new ListStateDescriptor<>("numbers", Types.INT));
368: 
369:             if (context.isRestored()) {
370:                 Set<Integer> expected = new HashSet<>();
371:                 expected.add(1);
372:                 expected.add(2);
373:                 expected.add(3);
374: 
375:                 for (Integer number : state.get()) {
376:                     Assert.assertTrue("Duplicate state", expected.contains(number));
377:                     expected.remove(number);
378:                 }
379: 
380:                 Assert.assertTrue(
381:                         "Failed to bootstrap all state elements: "
382:                                 + Arrays.toString(expected.toArray()),
383:                         expected.isEmpty());
384:             }
385:         }
386: 
387:         @Override
388:         public Integer map(Integer value) {
389:             return null;
390:         }
391:     }
392: 
393:     /** A broadcast bootstrap function. */
394:     public static class CurrencyBootstrapFunction
395:             extends BroadcastStateBootstrapFunction<CurrencyRate> {
396: 
397:         @Override
398:         public void processElement(CurrencyRate value, Context ctx) throws Exception {
399:             ctx.getBroadcastState(descriptor).put(value.currency, value.rate);
400:         }
401:     }
402: 
403:     /** Checks the restored broadcast state. */
404:     public static class CurrencyValidationFunction
405:             extends BroadcastProcessFunction<CurrencyRate, CurrencyRate, Void> {
406: 
407:         @Override
408:         public void processElement(CurrencyRate value, ReadOnlyContext ctx, Collector<Void> out)
409:                 throws Exception {
410:             Assert.assertEquals(
411:                     "Incorrect currency rate",
412:                     value.rate,
413:                     ctx.getBroadcastState(descriptor).get(value.currency),
414:                     0.0001);
415:         }
416: 
417:         @Override
418:         public void processBroadcastElement(CurrencyRate value, Context ctx, Collector<Void> out) {
419:             // ignore
420:         }
421:     }
422: }
