328:     private static void testExternalizedCheckpoints(
329:             File checkpointDir,
330:             String zooKeeperQuorum,
331:             StateBackend backend1,
332:             StateBackend backend2,
333:             StateBackend backend3,
334:             boolean localRecovery,
335:             RecoveryClaimMode recoveryClaimMode)
336:             throws Exception {
337: 
338:         final Configuration config = new Configuration();
339: 
340:         final File savepointDir = temporaryFolder.newFolder();
341: 
342:         config.set(CheckpointingOptions.CHECKPOINTS_DIRECTORY, checkpointDir.toURI().toString());
343:         config.set(CheckpointingOptions.SAVEPOINT_DIRECTORY, savepointDir.toURI().toString());
344:         config.set(StateRecoveryOptions.LOCAL_RECOVERY, localRecovery);
345: 
346:         // Configure DFS DSTL for this test as it might produce too much GC pressure if
347:         // ChangelogStateBackend is used.
348:         // Doing it on cluster level unconditionally as randomization currently happens on the job
349:         // level (environment); while this factory can only be set on the cluster level.
350:         FsStateChangelogStorageFactory.configure(
351:                 config, temporaryFolder.newFolder(), Duration.ofMinutes(1), 10);
352: 
353:         // ZooKeeper recovery mode?
354:         if (zooKeeperQuorum != null) {
355:             final File haDir = temporaryFolder.newFolder();
356:             config.set(HighAvailabilityOptions.HA_MODE, "ZOOKEEPER");
357:             config.set(HighAvailabilityOptions.HA_ZOOKEEPER_QUORUM, zooKeeperQuorum);
358:             config.set(HighAvailabilityOptions.HA_STORAGE_PATH, haDir.toURI().toString());
359:         }
360: 
361:         MiniClusterWithClientResource cluster =
362:                 new MiniClusterWithClientResource(
363:                         new MiniClusterResourceConfiguration.Builder()
364:                                 .setConfiguration(config)
365:                                 .setNumberTaskManagers(NUM_TASK_MANAGERS)
366:                                 .setNumberSlotsPerTaskManager(SLOTS_PER_TASK_MANAGER)
367:                                 .build());
368: 
369:         cluster.before();
370: 
371:         try {
372:             // main test sequence:  start job -> eCP -> restore job -> eCP -> restore job
373:             String firstExternalCheckpoint =
374:                     runJobAndGetExternalizedCheckpoint(backend1, null, cluster, recoveryClaimMode);
375:             assertNotNull(firstExternalCheckpoint);
376: 
377:             String secondExternalCheckpoint =
378:                     runJobAndGetExternalizedCheckpoint(
379:                             backend2, firstExternalCheckpoint, cluster, recoveryClaimMode);
380:             assertNotNull(secondExternalCheckpoint);
381: 
382:             String thirdExternalCheckpoint =
383:                     runJobAndGetExternalizedCheckpoint(
384:                             backend3,
385:                             // in CLAIM mode, the previous run is only guaranteed to preserve the
386:                             // latest checkpoint; in NO_CLAIM/LEGACY, even the initial checkpoints
387:                             // must remain valid
388:                             recoveryClaimMode == RecoveryClaimMode.CLAIM
389:                                     ? secondExternalCheckpoint
390:                                     : firstExternalCheckpoint,
391:                             cluster,
392:                             recoveryClaimMode);
393:             assertNotNull(thirdExternalCheckpoint);
394:         } finally {
395:             cluster.after();
396:         }
397:     }
