516:      * This {@link WatermarkStrategy} assigns the current system time as the event-time timestamp.
517:      * In a real use case you should use proper timestamps and an appropriate {@link
518:      * WatermarkStrategy}.
519:      */
520:     private static class IngestionTimeWatermarkStrategy<T> implements WatermarkStrategy<T> {
521: 
522:         private IngestionTimeWatermarkStrategy() {}
523: 
524:         public static <T> IngestionTimeWatermarkStrategy<T> create() {
525:             return new IngestionTimeWatermarkStrategy<>();
526:         }
527: 
528:         @Override
529:         public WatermarkGenerator<T> createWatermarkGenerator(
530:                 WatermarkGeneratorSupplier.Context context) {
531:             return new AscendingTimestampsWatermarks<>();
532:         }
533: 
534:         @Override
535:         public TimestampAssigner<T> createTimestampAssigner(
536:                 TimestampAssignerSupplier.Context context) {
537:             return (event, timestamp) -> System.currentTimeMillis();
538:         }
