40: /** The default implementation of he {@link CheckpointPlan}. */
41: public class DefaultCheckpointPlan implements CheckpointPlan {
42: 
43:     private final List<Execution> tasksToTrigger;
44: 
45:     private final List<Execution> tasksToWaitFor;
46: 
47:     private final List<ExecutionVertex> tasksToCommitTo;
48: 
49:     private final List<Execution> finishedTasks;
50: 
51:     private final boolean mayHaveFinishedTasks;
52: 
53:     private final Map<JobVertexID, ExecutionJobVertex> fullyFinishedOrFinishedOnRestoreVertices;
54: 
55:     private final IdentityHashMap<ExecutionJobVertex, Integer> vertexOperatorsFinishedTasksCount;
56: 
57:     DefaultCheckpointPlan(
58:             List<Execution> tasksToTrigger,
59:             List<Execution> tasksToWaitFor,
60:             List<ExecutionVertex> tasksToCommitTo,
61:             List<Execution> finishedTasks,
62:             List<ExecutionJobVertex> fullyFinishedJobVertex,
63:             boolean mayHaveFinishedTasks) {
64: 
65:         this.tasksToTrigger = checkNotNull(tasksToTrigger);
66:         this.tasksToWaitFor = checkNotNull(tasksToWaitFor);
67:         this.tasksToCommitTo = checkNotNull(tasksToCommitTo);
68:         this.finishedTasks = checkNotNull(finishedTasks);
69:         this.mayHaveFinishedTasks = mayHaveFinishedTasks;
70: 
71:         this.fullyFinishedOrFinishedOnRestoreVertices = new HashMap<>();
72:         fullyFinishedJobVertex.forEach(
73:                 jobVertex ->
74:                         fullyFinishedOrFinishedOnRestoreVertices.put(
75:                                 jobVertex.getJobVertexId(), jobVertex));
76: 
77:         this.vertexOperatorsFinishedTasksCount = new IdentityHashMap<>();
78:     }
