91:     public List<ExecutionVertex> getTasksToCommitTo() {
92:         return tasksToCommitTo;
93:     }
94: 
95:     @Override
96:     public List<Execution> getFinishedTasks() {
97:         return finishedTasks;
98:     }
99: 
