132:                 partlyFinishedVertex.put(jobVertexId, task.getVertex().getJobVertex());
133:             }
134:         }
135: 
136:         checkNoPartlyFinishedVertexUsedUnionListState(partlyFinishedVertex, operatorStates);
137:         checkNoPartlyOperatorsFinishedVertexUsedUnionListState(
138:                 partlyFinishedVertex, operatorStates);
139: 
140:         fulfillFullyFinishedOrFinishedOnRestoreOperatorStates(operatorStates);
141:         fulfillSubtaskStateForPartiallyFinishedOperators(operatorStates);
142:     }
143: 
144:     /**
145:      * If a job vertex using {@code UnionListState} has part of tasks FINISHED where others are
146:      * still in RUNNING state, the checkpoint would be aborted since it might cause incomplete
147:      * {@code UnionListState}.
148:      */
149:     private void checkNoPartlyFinishedVertexUsedUnionListState(
150:             Map<JobVertexID, ExecutionJobVertex> partlyFinishedVertex,
151:             Map<OperatorID, OperatorState> operatorStates) {
152:         for (ExecutionJobVertex vertex : partlyFinishedVertex.values()) {
153:             if (hasUsedUnionListState(vertex, operatorStates)) {
154:                 throw new PartialFinishingNotSupportedByStateException(
155:                         String.format(
156:                                 "The vertex %s (id = %s) has used"
157:                                         + " UnionListState, but part of its tasks are FINISHED.",
158:                                 vertex.getName(), vertex.getJobVertexId()));
159:             }
160:         }
161:     }
162: 
163:     /**
164:      * If a job vertex using {@code UnionListState} has all the tasks in RUNNING state, but part of
165:      * the tasks have reported that the operators are finished, the checkpoint would be aborted.
166:      * This is to force the fast tasks wait for the slow tasks so that their final checkpoints would
167:      * be the same one, otherwise if the fast tasks finished, the slow tasks would be blocked
168:      * forever since all the following checkpoints would be aborted.
169:      */
170:     private void checkNoPartlyOperatorsFinishedVertexUsedUnionListState(
171:             Map<JobVertexID, ExecutionJobVertex> partlyFinishedVertex,
172:             Map<OperatorID, OperatorState> operatorStates) {
173:         for (Map.Entry<ExecutionJobVertex, Integer> entry :
174:                 vertexOperatorsFinishedTasksCount.entrySet()) {
175:             ExecutionJobVertex vertex = entry.getKey();
176: 
177:             // If the vertex is partly finished, then it must not used UnionListState
178:             // due to it passed the previous check.
179:             if (partlyFinishedVertex.containsKey(vertex.getJobVertexId())) {
180:                 continue;
181:             }
182: 
183:             if (entry.getValue() != vertex.getParallelism()
184:                     && hasUsedUnionListState(vertex, operatorStates)) {
185:                 throw new PartialFinishingNotSupportedByStateException(
186:                         String.format(
187:                                 "The vertex %s (id = %s) has used"
188:                                         + " UnionListState, but part of its tasks has called operators' finish method.",
189:                                 vertex.getName(), vertex.getJobVertexId()));
190:             }
191:         }
192:     }
193: 
194:     private boolean hasUsedUnionListState(
195:             ExecutionJobVertex vertex, Map<OperatorID, OperatorState> operatorStates) {
196:         for (OperatorIDPair operatorIDPair : vertex.getOperatorIDs()) {
197:             OperatorState operatorState =
198:                     operatorStates.get(operatorIDPair.getGeneratedOperatorID());
199:             if (operatorState == null) {
200:                 continue;
201:             }
202: 
203:             for (OperatorSubtaskState operatorSubtaskState : operatorState.getStates()) {
204:                 boolean hasUnionListState =
205:                         Stream.concat(
206:                                         operatorSubtaskState.getManagedOperatorState().stream(),
207:                                         operatorSubtaskState.getRawOperatorState().stream())
208:                                 .filter(Objects::nonNull)
209:                                 .flatMap(
210:                                         operatorStateHandle ->
211:                                                 operatorStateHandle.getStateNameToPartitionOffsets()
212:                                                         .values().stream())
213:                                 .anyMatch(
214:                                         stateMetaInfo ->
215:                                                 stateMetaInfo.getDistributionMode()
216:                                                         == OperatorStateHandle.Mode.UNION);
217: 
218:                 if (hasUnionListState) {
219:                     return true;
220:                 }
221:             }
222:         }
223: 
224:         return false;
225:     }
226: 
227:     private void fulfillFullyFinishedOrFinishedOnRestoreOperatorStates(
228:             Map<OperatorID, OperatorState> operatorStates) {
229:         // Completes the operator state for the fully finished operators
230:         for (ExecutionJobVertex jobVertex : fullyFinishedOrFinishedOnRestoreVertices.values()) {
231:             for (OperatorIDPair operatorIDPair : jobVertex.getOperatorIDs()) {
232:                 OperatorState operatorState =
233:                         operatorStates.get(operatorIDPair.getGeneratedOperatorID());
234:                 checkState(
235:                         operatorState == null || !operatorState.hasSubtaskStates(),
236:                         "There should be no states or only coordinator state reported for fully finished operators");
237: 
238:                 operatorState =
239:                         new FullyFinishedOperatorState(
240:                                 operatorIDPair.getGeneratedOperatorID(),
241:                                 jobVertex.getParallelism(),
242:                                 jobVertex.getMaxParallelism());
243:                 operatorStates.put(operatorIDPair.getGeneratedOperatorID(), operatorState);
244:             }
245:         }
246:     }
247: 
248:     private void fulfillSubtaskStateForPartiallyFinishedOperators(
249:             Map<OperatorID, OperatorState> operatorStates) {
250:         for (Execution finishedTask : finishedTasks) {
251:             ExecutionJobVertex jobVertex = finishedTask.getVertex().getJobVertex();
252:             for (OperatorIDPair operatorIDPair : jobVertex.getOperatorIDs()) {
253:                 OperatorState operatorState =
254:                         operatorStates.get(operatorIDPair.getGeneratedOperatorID());
255: 
256:                 if (operatorState != null && operatorState.isFullyFinished()) {
257:                     continue;
258:                 }
259: 
260:                 if (operatorState == null) {
261:                     operatorState =
262:                             new OperatorState(
263:                                     operatorIDPair.getGeneratedOperatorID(),
264:                                     jobVertex.getParallelism(),
265:                                     jobVertex.getMaxParallelism());
266:                     operatorStates.put(operatorIDPair.getGeneratedOperatorID(), operatorState);
267:                 }
268: 
269:                 operatorState.putState(
270:                         finishedTask.getParallelSubtaskIndex(),
271:                         FinishedOperatorSubtaskState.INSTANCE);
272:             }
273:         }
274:     }
