39: class WaitingForResources extends StateWithoutExecutionGraph implements ResourceListener {
40: 
41:     private final Context context;
42: 
43:     private final Clock clock;
44: 
45:     /** If set, there's an ongoing deadline waiting for a resource stabilization. */
46:     @Nullable private Deadline resourceStabilizationDeadline;
47: 
48:     private final Duration stateTransitionManagerFactory;
49: 
50:     @Nullable private ScheduledFuture<?> resourceTimeoutFuture;
51: 
52:     @Nullable private final ExecutionGraph previousExecutionGraph;
53: 
54:     @VisibleForTesting
55:     WaitingForResources(
56:             Context context,
57:             Logger log,
58:             Duration initialResourceAllocationTimeout,
59:             Duration stateTransitionManagerFactory) {
60:         this(
61:                 context,
62:                 log,
63:                 initialResourceAllocationTimeout,
64:                 stateTransitionManagerFactory,
65:                 SystemClock.getInstance(),
66:                 null);
67:     }
68: 
69:     WaitingForResources(
70:             Context context,
71:             Logger log,
72:             Duration initialResourceAllocationTimeout,
73:             Duration resourceStabilizationTimeout,
74:             Clock clock,
75:             @Nullable ExecutionGraph previousExecutionGraph) {
76:         super(context, log);
77:         this.context = Preconditions.checkNotNull(context);
78:         this.stateTransitionManagerFactory =
79:                 Preconditions.checkNotNull(resourceStabilizationTimeout);
80:         this.clock = clock;
81:         Preconditions.checkNotNull(initialResourceAllocationTimeout);
82: 
83:         Preconditions.checkArgument(
84:                 !resourceStabilizationTimeout.isNegative(),
85:                 "Resource stabilization timeout must not be negative");
86: 
87:         // since state transitions are not allowed in state constructors, schedule calls for later.
88:         if (!initialResourceAllocationTimeout.isNegative()) {
89:             resourceTimeoutFuture =
90:                     context.runIfState(
91:                             this, this::resourceTimeout, initialResourceAllocationTimeout);
92:         }
93:         this.previousExecutionGraph = previousExecutionGraph;
94:         context.runIfState(this, this::checkDesiredOrSufficientResourcesAvailable, Duration.ZERO);
95:     }
96: 
97:     @Override
98:     public void onLeave(Class<? extends State> newState) {
99:         if (resourceTimeoutFuture != null) {
100:             resourceTimeoutFuture.cancel(false);
101:         }
102:     }
