464:             DeclarativeSlotPool declarativeSlotPool,
465:             SlotAllocator slotAllocator,
466:             Executor ioExecutor,
467:             ClassLoader userCodeClassLoader,
468:             CheckpointsCleaner checkpointsCleaner,
469:             CheckpointRecoveryFactory checkpointRecoveryFactory,
470:             JobManagerJobMetricGroup jobManagerJobMetricGroup,
471:             RestartBackoffTimeStrategy restartBackoffTimeStrategy,
472:             long initializationTimestamp,
473:             ComponentMainThreadExecutor mainThreadExecutor,
474:             FatalErrorHandler fatalErrorHandler,
475:             JobStatusListener jobStatusListener,
476:             Collection<FailureEnricher> failureEnrichers,
477:             ExecutionGraphFactory executionGraphFactory)
478:             throws JobExecutionException {
479: 
480:         assertPreconditions(jobGraph);
481: 
482:         this.settings = settings;
483:         this.rescaleManagerFactory = rescaleManagerFactory;
484: 
485:         this.jobGraph = jobGraph;
486:         this.jobInfo = new JobInfoImpl(jobGraph.getJobID(), jobGraph.getName());
487: 
488:         VertexParallelismStore vertexParallelismStore =
489:                 computeVertexParallelismStore(jobGraph, settings.getExecutionMode());
490:         if (jobResourceRequirements != null) {
491:             vertexParallelismStore =
492:                     DefaultVertexParallelismStore.applyJobResourceRequirements(
493:                                     vertexParallelismStore, jobResourceRequirements)
494:                             .orElse(vertexParallelismStore);
495:         }
496: 
497:         this.initialParallelismStore = vertexParallelismStore;
498:         this.jobInformation = new JobGraphJobInformation(jobGraph, vertexParallelismStore);
499: 
500:         this.declarativeSlotPool = declarativeSlotPool;
501:         this.initializationTimestamp = initializationTimestamp;
502:         this.ioExecutor = ioExecutor;
503:         this.userCodeClassLoader = userCodeClassLoader;
504:         this.restartBackoffTimeStrategy = restartBackoffTimeStrategy;
505:         this.fatalErrorHandler = fatalErrorHandler;
506:         this.checkpointsCleaner = checkpointsCleaner;
507:         this.completedCheckpointStore =
508:                 SchedulerUtils.createCompletedCheckpointStoreIfCheckpointingIsEnabled(
509:                         jobGraph, configuration, checkpointRecoveryFactory, ioExecutor, LOG);
510:         this.checkpointIdCounter =
511:                 SchedulerUtils.createCheckpointIDCounterIfCheckpointingIsEnabled(
512:                         jobGraph, checkpointRecoveryFactory);
513:         this.checkpointStatsTracker =
514:                 SchedulerUtils.createCheckpointStatsTrackerIfCheckpointingIsEnabled(
515:                         jobGraph,
516:                         () ->
517:                                 checkpointStatsTrackerFactory.apply(
518:                                         jobManagerJobMetricGroup, createCheckpointStatsListener()));
519: 
520:         this.slotAllocator = slotAllocator;
521: 
522:         declarativeSlotPool.registerNewSlotsListener(this::newResourcesAvailable);
523: 
524:         this.componentMainThreadExecutor = mainThreadExecutor;
525: 
526:         this.executionGraphFactory = executionGraphFactory;
527: 
528:         final JobStatusStore jobStatusStore = new JobStatusStore(initializationTimestamp);
529:         final Collection<JobStatusListener> tmpJobStatusListeners = new ArrayList<>();
530:         tmpJobStatusListeners.add(Preconditions.checkNotNull(jobStatusListener));
531:         tmpJobStatusListeners.add(jobStatusStore);
532: 
533:         final MetricOptions.JobStatusMetricsSettings jobStatusMetricsSettings =
534:                 MetricOptions.JobStatusMetricsSettings.fromConfiguration(configuration);
535: 
536:         deploymentTimeMetrics =
537:                 new DeploymentStateTimeMetrics(jobGraph.getJobType(), jobStatusMetricsSettings);
538: 
539:         SchedulerBase.registerJobMetrics(
540:                 jobManagerJobMetricGroup,
541:                 jobStatusStore,
542:                 () -> (long) numRestarts,
543:                 deploymentTimeMetrics,
544:                 tmpJobStatusListeners::add,
545:                 initializationTimestamp,
546:                 jobStatusMetricsSettings);
547: 
548:         jobStatusListeners = Collections.unmodifiableCollection(tmpJobStatusListeners);
549:         this.failureEnrichers = failureEnrichers;
550:         this.exceptionHistory =
551:                 new BoundedFIFOQueue<>(configuration.get(WebOptions.MAX_EXCEPTION_HISTORY_SIZE));
552:         this.jobManagerJobMetricGroup = jobManagerJobMetricGroup;
553: 
554:         this.jobFailureMetricReporter = new JobFailureMetricReporter(jobManagerJobMetricGroup);
555:         this.reportEventsAsSpans = configuration.get(TraceOptions.REPORT_EVENTS_AS_SPANS);
556:     }
