715:     private void stopCheckpointServicesSafely(JobStatus terminalState) {
716:         LOG.debug("Stopping the checkpoint services with state {}.", terminalState);
717: 
718:         Exception exception = null;
719: 
720:         try {
721:             completedCheckpointStore.shutdown(terminalState, checkpointsCleaner);
722:         } catch (Exception e) {
723:             exception = e;
724:         }
725: 
726:         try {
727:             checkpointIdCounter.shutdown(terminalState).get();
728:         } catch (Exception e) {
729:             exception = ExceptionUtils.firstOrSuppressed(e, exception);
730:         }
731: 
732:         if (exception != null) {
733:             LOG.warn("Failed to stop checkpoint services.", exception);
734:         }
735:     }
