636:     /**
637:      * Creates the parallelism store that should be used for determining scheduling requirements,
638:      * which may choose different parallelisms than set in the {@link JobGraph} depending on the
639:      * execution mode.
640:      *
641:      * @param jobGraph The job graph for execution.
642:      * @param executionMode The mode of scheduler execution.
643:      * @return The parallelism store.
644:      */
645:     private static VertexParallelismStore computeVertexParallelismStore(
646:             JobGraph jobGraph, SchedulerExecutionMode executionMode) {
647:         if (executionMode == SchedulerExecutionMode.REACTIVE) {
648:             return computeReactiveModeVertexParallelismStore(
649:                     jobGraph.getVertices(), SchedulerBase::getDefaultMaxParallelism, true);
650:         }
651:         return SchedulerBase.computeVertexParallelismStore(jobGraph);
652:     }
