1293:     private CompletableFuture<CreatingExecutionGraph.ExecutionGraphWithVertexParallelism>
1294:             createExecutionGraphWithAvailableResourcesAsync(
1295:                     @Nullable ExecutionGraph previousExecutionGraph) {
1296:         final JobSchedulingPlan schedulingPlan;
1297:         final VertexParallelismStore adjustedParallelismStore;
1298: 
1299:         try {
1300:             schedulingPlan = determineParallelism(slotAllocator, previousExecutionGraph);
1301:             JobGraph adjustedJobGraph = jobInformation.copyJobGraph();
1302: 
1303:             for (JobVertex vertex : adjustedJobGraph.getVertices()) {
1304:                 JobVertexID id = vertex.getID();
1305: 
1306:                 // use the determined "available parallelism" to use
1307:                 // the resources we have access to
1308:                 vertex.setParallelism(schedulingPlan.getVertexParallelism().getParallelism(id));
1309:             }
1310: 
1311:             // use the originally configured max parallelism
1312:             // as the default for consistent runs
1313:             adjustedParallelismStore =
1314:                     computeVertexParallelismStoreForExecution(
1315:                             adjustedJobGraph,
1316:                             settings.getExecutionMode(),
1317:                             (vertex) -> {
1318:                                 VertexParallelismInformation vertexParallelismInfo =
1319:                                         initialParallelismStore.getParallelismInfo(vertex.getID());
1320:                                 return vertexParallelismInfo.getMaxParallelism();
1321:                             });
1322:         } catch (Exception exception) {
1323:             return FutureUtils.completedExceptionally(exception);
1324:         }
1325: 
1326:         return createExecutionGraphAndRestoreStateAsync(adjustedParallelismStore)
1327:                 .thenApply(
1328:                         executionGraph ->
1329:                                 CreatingExecutionGraph.ExecutionGraphWithVertexParallelism.create(
1330:                                         executionGraph, schedulingPlan));
1331:     }
