1280:     @Override
1281:     public void goToCreatingExecutionGraph(@Nullable ExecutionGraph previousExecutionGraph) {
1282:         final CompletableFuture<CreatingExecutionGraph.ExecutionGraphWithVertexParallelism>
1283:                 executionGraphWithAvailableResourcesFuture =
1284:                         createExecutionGraphWithAvailableResourcesAsync(previousExecutionGraph);
1285:         transitionToState(
