695:     @Override
696:     public CompletableFuture<Void> closeAsync() {
697:         LOG.debug("Closing the AdaptiveScheduler. Trying to suspend the current job execution.");
698: 
699:         state.suspend(new FlinkException("AdaptiveScheduler is being stopped."));
700: 
701:         Preconditions.checkState(
702:                 state instanceof Finished,
703:                 "Scheduler state should be finished after calling state.suspend.");
704: 
705:         backgroundTask.abort();
706:         // wait for the background task to finish and then close services
707:         return FutureUtils.composeAfterwards(
708:                 FutureUtils.runAfterwardsAsync(
709:                         backgroundTask.getTerminationFuture(),
710:                         () -> stopCheckpointServicesSafely(jobTerminationFuture.get()),
711:                         getMainThreadExecutor()),
712:                 checkpointsCleaner::closeAsync);
713:     }
