1444:     private FailureResult howToHandleFailure(Throwable failure) {
1445:         if (ExecutionFailureHandler.isUnrecoverableError(failure)) {
1446:             return FailureResult.canNotRestart(
1447:                     new JobException("The failure is not recoverable", failure));
1448:         }
1449: 
1450:         restartBackoffTimeStrategy.notifyFailure(failure);
1451:         if (restartBackoffTimeStrategy.canRestart()) {
1452:             return FailureResult.canRestart(
1453:                     failure, Duration.ofMillis(restartBackoffTimeStrategy.getBackoffTime()));
1454:         } else {
1455:             return FailureResult.canNotRestart(
1456:                     new JobException(
1457:                             "Recovery is suppressed by " + restartBackoffTimeStrategy, failure));
1458:         }
1459:     }
