197: 
198:         public static Settings of(
199:                 Configuration configuration,
200:                 @Nullable JobCheckpointingSettings checkpointingConfiguration)
201:                 throws ConfigurationException {
202:             final SchedulerExecutionMode executionMode =
203:                     configuration.get(JobManagerOptions.SCHEDULER_MODE);
204:             Duration allocationTimeoutDefault =
205:                     JobManagerOptions.RESOURCE_WAIT_TIMEOUT.defaultValue();
206:             Duration stabilizationTimeoutDefault =
207:                     JobManagerOptions.RESOURCE_STABILIZATION_TIMEOUT.defaultValue();
208:             if (executionMode == SchedulerExecutionMode.REACTIVE) {
209:                 allocationTimeoutDefault = Duration.ofMillis(-1);
210:                 stabilizationTimeoutDefault = Duration.ZERO;
211:             }
212: 
213:             final Duration scalingIntervalMin =
214:                     configuration.get(JobManagerOptions.SCHEDULER_SCALING_INTERVAL_MIN);
215:             final Duration scalingIntervalMax =
216:                     configuration.get(JobManagerOptions.SCHEDULER_SCALING_INTERVAL_MAX);
217:             Preconditions.checkState(
218:                     !scalingIntervalMin.isNegative(),
219:                     "%s must be positive integer or 0",
220:                     JobManagerOptions.SCHEDULER_SCALING_INTERVAL_MIN.key());
221:             if (scalingIntervalMax != null) {
222:                 Preconditions.checkState(
223:                         scalingIntervalMax.compareTo(scalingIntervalMin) > 0,
224:                         "%s(%d) must be greater than %s(%d)",
225:                         JobManagerOptions.SCHEDULER_SCALING_INTERVAL_MAX.key(),
226:                         scalingIntervalMax,
227:                         JobManagerOptions.SCHEDULER_SCALING_INTERVAL_MIN.key(),
228:                         scalingIntervalMin);
229:             }
230: 
231:             final int rescaleOnFailedCheckpointsCount =
232:                     configuration.get(
233:                             JobManagerOptions.SCHEDULER_SCALE_ON_FAILED_CHECKPOINTS_COUNT);
234:             if (rescaleOnFailedCheckpointsCount < 1) {
235:                 throw new ConfigurationException(
236:                         String.format(
237:                                 "%s should have a value of 1 or higher.",
238:                                 JobManagerOptions.SCHEDULER_SCALE_ON_FAILED_CHECKPOINTS_COUNT
239:                                         .key()));
240:             }
241: 
242:             // default value generation is documented in JobManagerOption
243:             final Duration maximumDelayForRescaleTriggerDefault =
244:                     checkpointingConfiguration != null
245:                                     && checkpointingConfiguration
246:                                             .getCheckpointCoordinatorConfiguration()
247:                                             .isCheckpointingEnabled()
248:                             // incrementing the rescaleOnFailedCheckpointsCount by 1 is done to
249:                             // avoid introducing a race-condition between the two parameters
250:                             // (SCHEDULER_SCALE_ON_FAILED_CHECKPOINTS_COUNT and
251:                             // MAXIMUM_DELAY_FOR_SCALE_TRIGGER). Without the increment, we would
252:                             // have two configuration parameters that result in roughly the same
253:                             // timeout (with the MAXIMUM_DELAY_FOR_SCALE_TRIGGER being probably a
254:                             // bit faster). The user might experience unexpected behavior if the
255:                             // SCHEDULER_SCALE_ON_FAILED_CHECKPOINTS_COUNT is configured and
256:                             // MAXIMUM_DELAY_FOR_SCALE_TRIGGER is kept untouched in that case.
257:                             // Incrementing the default value should help avoiding causing this kind
258:                             // of confusing race condition.
259:                             ? Duration.ofMillis(
260:                                     (rescaleOnFailedCheckpointsCount + 1)
261:                                             * checkpointingConfiguration
262:                                                     .getCheckpointCoordinatorConfiguration()
263:                                                     .getCheckpointInterval())
264:                             : Duration.ZERO;
265: 
266:             return new Settings(
267:                     executionMode,
268:                     configuration
269:                             .getOptional(JobManagerOptions.RESOURCE_WAIT_TIMEOUT)
270:                             .orElse(allocationTimeoutDefault),
271:                     configuration
272:                             .getOptional(JobManagerOptions.RESOURCE_STABILIZATION_TIMEOUT)
273:                             .orElse(stabilizationTimeoutDefault),
274:                     configuration.get(JobManagerOptions.SLOT_IDLE_TIMEOUT),
275:                     scalingIntervalMin,
276:                     scalingIntervalMax,
277:                     configuration.get(MIN_PARALLELISM_INCREASE),
278:                     configuration.get(
279:                             MAXIMUM_DELAY_FOR_SCALE_TRIGGER, maximumDelayForRescaleTriggerDefault),
280:                     rescaleOnFailedCheckpointsCount);
281:         }
