560:          */
561:         public DefaultRescaleManager createTestInstanceInSoftRescalePhase() {
562:             return createTestInstance(this::transitionIntoSoftScalingTimeframe);
563:         }
564: 
565:         /**
566:          * Creates the {@code DefaultRescaleManager} test instance and transitions into a period in
567:          * time where the instance is in hard-rescaling phase.
568:          */
569:         public DefaultRescaleManager createTestInstanceInHardRescalePhase() {
570:             return createTestInstance(this::transitionIntoHardScalingTimeframe);
571:         }
572: 
573:         /**
574:          * Initializes the test instance and sets the context's elapsed time based on the passed
575:          * callback.
576:          */
577:         private DefaultRescaleManager createTestInstance(Runnable timeTransitioning) {
578:             final DefaultRescaleManager testInstance =
579:                     new DefaultRescaleManager(
580:                             initializationTime,
581:                             // clock that returns the time based on the configured elapsedTime
582:                             () -> Objects.requireNonNull(initializationTime).plus(elapsedTime),
583:                             this,
584:                             SCALING_MIN,
585:                             SCALING_MAX,
586:                             Duration.ofHours(5)) {
587:                         @Override
588:                         public void onChange() {
589:                             super.onChange();
590: 
591:                             // hack to avoid calling this method in every test method
592:                             // we want to trigger tasks that are meant to run right-away
593:                             TestingRescaleManagerContext.this.triggerOutdatedTasks();
594:                         }
595: 
596:                         @Override
597:                         public void onTrigger() {
598:                             super.onTrigger();
599: 
600:                             // hack to avoid calling this method in every test method
601:                             // we want to trigger tasks that are meant to run right-away
602:                             TestingRescaleManagerContext.this.triggerOutdatedTasks();
603:                         }
604:                     };
605: 
606:             timeTransitioning.run();
607:             return testInstance;
608:         }
609: 
610:         // ///////////////////////////////////////////////
611:         // Time-adjustment functionality
612:         // ///////////////////////////////////////////////
613: 
614:         /**
615:          * Transitions the context's time to a moment that falls into the test instance's cooldown
616:          * phase.
617:          */
618:         public void transitionIntoCooldownTimeframe() {
619:             this.elapsedTime = SCALING_MIN.dividedBy(2);
620:             this.triggerOutdatedTasks();
621:         }
622: 
623:         /**
624:          * Transitions the context's time to a moment that falls into the test instance's
625:          * soft-scaling phase.
626:          */
627:         public void transitionIntoSoftScalingTimeframe() {
628:             // the state transition is scheduled based on the current event's time rather than the
629:             // initializationTime
630:             this.elapsedTime = elapsedTime.plus(SCALING_MIN);
631: 
632:             // make sure that we're still below the scalingIntervalMax
633:             this.elapsedTime = elapsedTime.plus(SCALING_MAX.minus(elapsedTime).dividedBy(2));
634:             this.triggerOutdatedTasks();
635:         }
636: 
637:         /**
638:          * Transitions the context's time to a moment that falls into the test instance's
639:          * hard-scaling phase.
640:          */
641:         public void transitionIntoHardScalingTimeframe() {
642:             // the state transition is scheduled based on the current event's time rather than the
643:             // initializationTime
644:             this.elapsedTime = elapsedTime.plus(SCALING_MAX).plusMinutes(1);
645:             this.triggerOutdatedTasks();
646:         }
647: 
648:         private void triggerOutdatedTasks() {
649:             while (!scheduledTasks.isEmpty()) {
650:                 final Instant timeOfExecution = scheduledTasks.firstKey();
651:                 if (!timeOfExecution.isAfter(
652:                         Objects.requireNonNull(initializationTime).plus(elapsedTime))) {
653:                     scheduledTasks.remove(timeOfExecution).forEach(Runnable::run);
654:                 } else {
655:                     break;
656:                 }
657:             }
658:         }
659: 
660:         // ///////////////////////////////////////////////
661:         // Methods for verifying the context's state
662:         // ///////////////////////////////////////////////
663: 
664:         public boolean rescaleWasTriggered() {
665:             return rescaleTriggered.get();
666:         }
667: 
668:         public int numberOfTasksWaiting() {
669:             return scheduledTasks.size();
670:         }
671: 
672:         public boolean additionalTasksWaiting() {
673:             return !scheduledTasks.isEmpty();
674:         }
675:     }
676: }
