162:                             context.getTaskNumber(),
163:                             context.getAttemptNumber(),
164:                             outputFileConfig);
165:             PartitionWriter.Context<T> writerContext =
166:                     new PartitionWriter.Context<>(parameters, formatFactory);
167:             writer =
168:                     PartitionWriterFactory.<T>get(
169:                                     partitionColumns.length - staticPartitions.size() > 0,
170:                                     dynamicGrouped,
171:                                     staticPartitions)
172:                             .create(
173:                                     writerContext,
174:                                     fileManager,
175:                                     computer,
